import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class Solver {
        int n, m;

        void solve(InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            long ans = 0;

            if (n > 100) {
                int rem = (n - 100) % 6;
                long q = (n - 100) / 6;
                ans += q * 6L * m;
                n = 100 + rem;
            }

            if (m > 100) {
                int rem = (m - 100) % 6;
                long q = (m - 100) / 6;
                ans += q * 6L * n;
                m = 100 + rem;
            }

            int[][] id = new int[n + 1][m + 1];
            int even = 1, odd = 1;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) == 0) id[i][j] = even++;
                }
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) != 0) id[i][j] = odd++;
                }
            }

            int L = even - 1;
            int R = odd - 1;

            int source = 0;
            int sink = L + R + 1;
            Dinic dinic = new Dinic(sink + 1);

            for (int i = 1; i <= L; i++) {
                dinic.addEdge(source, i, 1);
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) == 0) {
                        addFlowEdge(dinic, id, L, i, j, i - 3, j);
                        addFlowEdge(dinic, id, L, i, j, i - 2, j - 1);
                        addFlowEdge(dinic, id, L, i, j, i - 2, j + 1);
                        addFlowEdge(dinic, id, L, i, j, i, j - 3);
                        addFlowEdge(dinic, id, L, i, j, i - 1, j - 2);
                        addFlowEdge(dinic, id, L, i, j, i + 1, j - 2);
                        addFlowEdge(dinic, id, L, i, j, i, j + 3);
                        addFlowEdge(dinic, id, L, i, j, i - 1, j + 2);
                        addFlowEdge(dinic, id, L, i, j, i + 1, j + 2);
                        addFlowEdge(dinic, id, L, i, j, i + 3, j);
                        addFlowEdge(dinic, id, L, i, j, i + 2, j - 1);
                        addFlowEdge(dinic, id, L, i, j, i + 2, j + 1);
                    }
                }
            }

            for (int r = 1; r <= R; r++) {
                dinic.addEdge(L + r, sink, 1);
            }

            ans += 2L * dinic.maxFlow(source, sink);
            out.println(ans);
        }

        void addFlowEdge(Dinic dinic, int[][] id, int L, int i, int j, int s, int t) {
            if (s <= 0 || t <= 0 || s > n || t > m) return;
            int left = id[i][j];
            int right = id[s][t];
            dinic.addEdge(left, L + right, 1);
        }
    }

    static class Dinic {
        int n;
        ArrayList<Edge>[] g;
        int[] level;
        int[] iter;

        Dinic(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            iter = new int[n];
        }

        void addEdge(int from, int to, int cap) {
            Edge fwd = new Edge(to, g[to].size(), cap);
            Edge rev = new Edge(from, g[from].size(), 0);
            g[from].add(fwd);
            g[to].add(rev);
        }

        int maxFlow(int s, int t) {
            int flow = 0;
            while (bfs(s, t)) {
                Arrays.fill(iter, 0);
                int pushed;
                while ((pushed = dfs(s, t, Integer.MAX_VALUE)) > 0) {
                    flow += pushed;
                }
            }
            return flow;
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        int dfs(int v, int t, int f) {
            if (v == t) return f;
            for (; iter[v] < g[v].size(); iter[v]++) {
                Edge e = g[v].get(iter[v]);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    int d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        static class Edge {
            int to, rev, cap;

            Edge(int to, int rev, int cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }
    }
}
